import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { expect, within } from 'storybook/test';
import { ZimmProductStyleCode } from '.';

const meta: Meta<typeof ZimmProductStyleCode> = {
  title: 'Commerce/ZimmProductStyleCode',
  component: ZimmProductStyleCode,
  argTypes: {
    value: { control: 'text' },
  },
};
export default meta;

type Story = StoryObj<typeof ZimmProductStyleCode>;

export const Default: Story = {
  args: { value: '8637DS241' },
  play: async ({ canvasElement }) => {
    // The DS models label and value as two nodes while both composed page designs show one
    // concatenated string. This pins down that the two-node structure still reads as the
    // single line "Style Code: 8637DS241" to a screen reader and to visual comparison.
    const root = within(canvasElement).getByTestId('product-style-code');
    await expect(root.textContent?.replace(/\s+/g, ' ').trim()).toBe('Style Code: 8637DS241');
  },
};

export const Absent: Story = {
  name: 'No style code — renders nothing',
  args: { value: undefined },
  play: async ({ canvasElement }) => {
    await expect(within(canvasElement).queryByTestId('product-style-code')).not.toBeInTheDocument();
  },
};

