/**
 * Scoped to this atom's own contract per testing.md: given a value or no value, does it render
 * the right branch, does the label reach the DOM joined to the value as one readable line, and
 * is that label *sourced* from `react-intl` rather than written into the component.
 *
 * The recipe's own resolution is covered by theme/components/recipeGuards.test.ts and
 * ui-kits/recipeParts.test.ts; the visual result is covered by index.stories.tsx. Neither of
 * those proves the absent-value branch is discoverable from this folder, which is what this is.
 *
 * Every render is wrapped: the atom calls `useIntl()`, which throws outside an `IntlProvider`
 * (react-intl's `invariantIntlContext`). `.storybook/preview.tsx` supplies one for the stories;
 * Vitest has no global provider, so it is supplied here.
 */
import React from 'react';
import { describe, test, expect } from 'vitest';
import { render, screen } from '@testing-library/react';
import { IntlProvider } from 'react-intl';
import { ZimmProductStyleCode } from './index';

/** The id the component asks for. Repeated deliberately — see the sourcing test below. */
const LABEL_ID = 'product_view.label.style_code';

/**
 * `locale` matches `defaultLocale` so react-intl treats an absent message as the ordinary
 * fallback-to-`defaultMessage` path rather than a missing-translation error.
 */
const renderWithIntl = (ui: React.ReactElement, messages?: Record<string, string>) =>
  render(
    <IntlProvider locale="en-AU" defaultLocale="en-AU" messages={messages}>
      {ui}
    </IntlProvider>,
  );

describe('ZimmProductStyleCode', () => {
  test('renders the label and value as one readable line', () => {
    renderWithIntl(<ZimmProductStyleCode value="8637DS241" />);
    // The DS models label and value as two nodes; a screen reader and a copy-paste must still
    // see the single string both composed page designs show. With no message supplied this is
    // the `defaultMessage` path, which is what every locale renders until extraction runs.
    expect(screen.getByTestId('product-style-code').textContent).toBe('Style Code: 8637DS241');
  });

  test('takes the label from the intl provider rather than a literal in the component', () => {
    // The guard against a regression to `const LABEL = 'Style Code:'`. A hardcoded English
    // literal ships one language to all eleven locales, and it is invisible: the test above
    // passes either way, because `defaultMessage` and the old literal are the same string.
    // Supplying a different message for the same id is the only thing that tells them apart —
    // an inlined literal cannot change, so this assertion can only pass if the label was looked
    // up. The value must stay untouched, since it is a prop and not translatable copy.
    renderWithIntl(<ZimmProductStyleCode value="8637DS241" />, { [LABEL_ID]: 'Code de style :' });

    expect(screen.getByTestId('product-style-code').textContent).toBe('Code de style : 8637DS241');
  });

  test.each([undefined, ''])('renders nothing for %s', (value) => {
    renderWithIntl(<ZimmProductStyleCode value={value} />);
    // The page places this unconditionally, so an absent style code must collapse rather than
    // leave an empty styled node contributing to the stack's rhythm.
    expect(screen.queryByTestId('product-style-code')).not.toBeInTheDocument();
  });
});

import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmProductModelInfo } from 'app/components/ui-kits/atoms/zimmProductModelInfo';
import { ZimmProductStyleCode } from 'app/components/ui-kits/atoms/zimmProductStyleCode';
import { isBlankRichText } from 'app/utils/richText';

const ZIMM_PRODUCT_META_RECIPE = 'ZimmProductMeta';

type ZimmProductMetaProps = {
  /**
   * Model copy from the product's `c_modelFit` attribute, rich text as authored in Business
   * Manager. Not populated on most catalogue products today.
   */
  modelInfo?: string;
  /**
   * The master product's style number. Named to match `PdpProductInfo`'s field rather than the
   * atom's `value`, so the page can hand this block the mapper's output directly.
   */
  styleCode?: string;
};

/**
 * Molecule — the PDP meta block: the model line and the style code, in the order the design
 * places them beneath the accordions at the bottom of the info column.
 *
 * Both children already collapse on their own, so this exists for the spacing: the recipe owns
 * the 28px above the block and the 28px between its two rows.
 */
export const ZimmProductMeta = ({ modelInfo, styleCode }: ZimmProductMetaProps) => {
  const styles = useMultiStyleConfig(ZIMM_PRODUCT_META_RECIPE, {});

  // LOAD-BEARING, not a redundant echo of the children's own guards. Every other collapse in
  // ui-kits/ happens in an atom and the parent spaces whatever rendered with `gap` alone —
  // zimmProductContent.css.ts documents exactly that, and it works because a `gap` applies only
  // between rendered items, so an all-null column measures zero. This recipe also carries a
  // `paddingTop`, and padding is unconditional: without this guard, a product with neither a
  // style code nor model copy would still push 28px of empty space below the accordions.
  //
  // The predicate deliberately repeats zimmProductModelInfo/index.tsx:19's
  // `isBlankRichText(modelInfo)`. DRY holds at the logic level — `isBlankRichText`
  // (app/utils/richText.tsx) is the one shared implementation — so what repeats is the
  // *decision* about what counts as absent. If the atom's guard ever changes, this must follow.
  if (isBlankRichText(modelInfo) && !styleCode) return null;

  return (
    <chakra.div __css={styles.root} data-testid="product-meta">
      <ZimmProductModelInfo modelInfo={modelInfo} />
      <ZimmProductStyleCode value={styleCode} />
    </chakra.div>
  );
};

import { defineStyleConfig } from '@chakra-ui/react';

// Vertical leading around the label. Figma's footer-item allows equal space above and
// below the text and lets the item height follow the line count — 24px for one line,
// 38px for two (node 40000407:11736 > About Section > Links). Its text boxes are
// cap-height (8px one line, 22px two) where a browser line box is not, so the rule
// transfers rather than the numbers. The inner span reserves 1px for the underline
// indicator, so a line box measures 15px and two measure 29px; 4.5px each side yields
// 15+9=24 and 29+9=38 exactly. No 4.5px entry exists in spacing.ts — same provisional
// treatment as zimmButton.css.ts's BTN_PADDING_Y, pending UI-designer sign-off.
const NAV_ITEM_PAD_Y = '4.5px';

const baseStyle = {
  // textStyle is expanded in place by Chakra's style engine; fontFamily below
  // deliberately overrides it — Figma Default/Navigation binds brand/font/family/body,
  // not the heading family textStyles.navigation carries.
  textStyle: 'navigation',
  fontFamily: 'var(--zimm-font-family-body)',
  display: 'inline-flex',
  // Figma h-[24px] is a FLOOR, not a fixed height — the design's own ABOUT column
  // wraps "ACKNOWLEDGEMENT OF COUNTRY" onto two lines. minHeight keeps the 24px
  // target while letting multi-line labels grow, so no caller needs to override it.
  minHeight: 'var(--zimm-scale-xl)', // 1.5rem (24px) — Figma: h-[24px]
  // Height comes from lineHeight + padding, not from centring inside minHeight.
  // Centring only distributes space a single line leaves over, so a wrapped label
  // overflowed the floor and lost its leading entirely — the second line of
  // "ACKNOWLEDGEMENT OF COUNTRY" sat flush against the item above it.
  lineHeight: 'var(--zimm-font-lineheight-4xs)', // 0.875rem (14px)
  paddingBlock: NAV_ITEM_PAD_Y,
  justifyContent: 'center',
  alignItems: 'center',
  whiteSpace: 'normal',
  cursor: 'pointer',
  background: 'none',
  border: 'none',
  // paddingInline, not the `padding` shorthand: a shorthand here would sit after
  // paddingBlock above and reset it back to 0.
  paddingInline: 0,
  textDecoration: 'none',
  // Inner span carries the underline. Use transparent instead of 'none' so
  // border-color transitions smoothly on hover/active without a display change.
  '& > span': {
    borderBottom: 'var(--zimm-border-width-default) solid transparent',
    transition: `border-color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard)`,
  },
  _hover: {
    '& > span': { borderBottomColor: 'currentColor' },
  },
  // Active (aria-current="page"): permanent underline regardless of hover
  '&[aria-current="page"] > span': {
    borderBottomColor: 'currentColor',
  },
};

const variants = {
  light: {
    color: 'var(--zimm-color-text-default)',
    _focusVisible: {
      outline: 'var(--zimm-focus-ring)',
      outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      boxShadow: 'none',
    },
  },
  inverse: {
    color: 'var(--zimm-color-text-inverse)',
    _focusVisible: {
      outline: 'var(--zimm-border-width-default) solid var(--zimm-color-text-inverse)',
      outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      boxShadow: 'none',
    },
  },
};

export const ZimmNavItem = defineStyleConfig({
  baseStyle,
  variants,
  defaultProps: { variant: 'light' },
});

