/**
 * Ambient module declarations for @salesforce/retail-react-app.
 *
 * This package ships without TypeScript types. We declare the modules we
 * import in overrides/ with real types where we know the shape, and fall
 * back to an untyped catch-all for everything else.
 *
 * Add specific declarations here as more subpaths are consumed in overrides/.
 */

declare module '@salesforce/retail-react-app/app/theme' {
  import type { ChakraTheme } from '@chakra-ui/react';
  const theme: ChakraTheme;
  export default theme;
}

// Matches the pinned react-router-dom 5.3.4 (see package.json) — the package ships
// without its own types and no @types/react-router-dom is installed, so this mirrors
// that version's real shapes (history's Location/LocationDescriptor, match) rather
// than a generic approximation.
declare module 'react-router-dom' {
  import type React from 'react';

  interface Location<TState = unknown> {
    pathname: string;
    search: string;
    hash: string;
    state: TState;
    key?: string;
  }
  export function useLocation<TState = unknown>(): Location<TState>;

  // history 4.x, as bundled by react-router-dom 5.3.4. Only the members consumed in
  // overrides/ are declared — push is used by the footer's wordmark handler.
  interface History<TState = unknown> {
    push(path: string, state?: TState): void;
    replace(path: string, state?: TState): void;
    goBack(): void;
    location: Location<TState>;
  }
  export function useHistory<TState = unknown>(): History<TState>;

  // Every declared param is optional — a route pattern doesn't guarantee a segment
  // was actually present in the matched URL. Default is `{}` in the real react-router
  // types (so an unparameterised useParams()'s properties correctly fail to resolve);
  // `NonNullable<unknown>` is the eslint-approved equivalent — our ban-types rule
  // rejects a literal `{}`, and `Record<string, never>` was tried and rejected in
  // review: it types every property as `never`, which is assignable to anything and
  // so silently passes property access that should be a compile error.
  export function useParams<TParams extends { [K in keyof TParams]?: string } = NonNullable<unknown>>(): TParams;

  type To<TState = unknown> = string | { pathname?: string; search?: string; hash?: string; state?: TState };

  interface LinkProps<TState = unknown> extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
    to: To<TState>;
    replace?: boolean;
  }
  export const Link: React.ForwardRefExoticComponent<LinkProps & React.RefAttributes<HTMLAnchorElement>>;

  interface match<TParams extends { [K in keyof TParams]?: string } = NonNullable<unknown>> {
    params: TParams;
    isExact: boolean;
    path: string;
    url: string;
  }

  interface NavLinkProps extends LinkProps {
    exact?: boolean;
    activeClassName?: string;
    activeStyle?: React.CSSProperties;
    isActive?: (match: match | null, location: Location) => boolean;
  }
  export const NavLink: React.ForwardRefExoticComponent<NavLinkProps & React.RefAttributes<HTMLAnchorElement>>;

  // Test-only: wraps a component tree in a router without touching the real browser history.
  // Used by component tests exercising useHistory/useLocation (e.g. footer/index.test.tsx).
  interface MemoryRouterProps<TState = unknown> {
    initialEntries?: ReadonlyArray<string | To<TState>>;
    initialIndex?: number;
    children?: React.ReactNode;
  }
  export const MemoryRouter: React.FC<MemoryRouterProps>;
}

declare module '@salesforce/pwa-kit-react-sdk/ssr/universal/utils' {
  export function getAssetUrl(path: string): string;
}

declare module '@salesforce/pwa-kit-runtime/utils/ssr-config' {
  export function getConfig(): { app: Record<string, unknown> };
}

declare module '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks' {
  type ServerResponse = {
    set: (name: string, value: string) => void;
    status: (code: number) => ServerResponse;
  };
  export function useServerContext(): {
    req?: any;
    res?: ServerResponse;
  };
  export function useCorrelationId(): { correlationId: string };
}

declare module '@salesforce/pwa-kit-runtime/utils/ssr-namespace-paths' {
  export const getEnvBasePath: () => string;
  export const slasPrivateProxyPath: string;
  export const bundleBasePath: string;
}

declare module '@salesforce/pwa-kit-runtime/utils/logger-factory' {
  const createLogger: (opts: { packageName: string }) => any;
  export default createLogger;
}

declare module '@salesforce/pwa-kit-react-sdk/ssr/universal/components/with-react-query' {
  export function withReactQuery(Component: any, options?: any): any;
}

declare module '@salesforce/pwa-kit-react-sdk/utils/url' {
  export function getAppOrigin(): string;
}

declare module '@loadable/component' {
  const loadable: (fn: () => Promise<any>, opts?: any) => any;
  export default loadable;
}

// Static asset imports (webpack url-loader / asset modules)
declare module '*.svg' {
  const src: string;
  export default src;
}

// react-helmet 6.1.0 ships no types and @types/react-helmet is not installed (adding a
// package needs Integration approval — see AGENTS.md Hard Rule #7). This declares the
// surface overrides/ actually uses: <Helmet> with element children.
declare module 'react-helmet' {
  import type React from 'react';

  interface HelmetProps {
    children?: React.ReactNode;
    defer?: boolean;
    encodeSpecialCharacters?: boolean;
    htmlAttributes?: Record<string, string>;
    bodyAttributes?: Record<string, string>;
    titleTemplate?: string;
    defaultTitle?: string;
  }

  export const Helmet: React.ComponentType<HelmetProps>;
  export default Helmet;
}

// Mirrors node_modules/@salesforce/pwa-kit-react-sdk/ssr/universal/errors.js. `status` is
// optional on the constructor because callers derive it from an API response that may not
// carry one — the base retail-react-app PDP passes a possibly-undefined status through.
declare module '@salesforce/pwa-kit-react-sdk/ssr/universal/errors' {
  export class HTTPError extends Error {
    constructor(status?: number, message?: string);
    status?: number;
    toString(): string;
  }

  export class HTTPNotFound extends HTTPError {
    constructor(message?: string);
  }
}

// Catch-all for all other @salesforce/retail-react-app subpaths not declared above.
declare module '@salesforce/retail-react-app/*';

// @vitejs/plugin-react uses package exports only (no root index.d.ts), which
// TypeScript 4.9 with moduleResolution:node cannot resolve. Minimal shim — the
// actual Plugin return type depends on vite types that are equally unreachable
// from TS 4.9. Once the project upgrades to TS 5+ this declaration can be removed.
declare module '@vitejs/plugin-react' {
  interface Options {
    include?: string | RegExp | Array<string | RegExp>;
    exclude?: string | RegExp | Array<string | RegExp>;
    jsxImportSource?: string;
  }
  // Return typed as any: Plugin from vite is not resolvable under moduleResolution:node.
  function react(options?: Options): any;
  export default react;
}

import React from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { MemoryRouter } from 'react-router-dom';
import { Box } from '@chakra-ui/react';
import { expect, within } from 'storybook/test';
import { StaticProductHeader } from './staticProductHeader';

/*
 * A reasoned deviation from components.md's "Pages get a story showing the full assembly with
 * representative props — not a story per sub-section", declared in the PR body rather than
 * presented as compliance. Storying the PDP itself would mean stubbing ~30 hook call sites
 * including `useProduct`, which cuts against the direction to prefer real SFCC data; #59 set
 * the precedent of storying the presentational `Footer` rather than the fetching container.
 */

/** Real Shopper Products fields for 8637DS241 (ZimmermannAU, 2026-08-23). */
const PRODUCT = {
  id: '8637DS241-BLUEB-6',
  name: 'Natura Long Sleeve Linen Mini Dress',
  longDescription:
    '<p>A long sleeve linen mini dress featuring a deep v-neckline with fitted bodice and full skirt.</p>',
  master: { masterId: '8637DS241' },
  c_modelFit: 'Model is 178cm / 5ft 10in and wears a size 1.',
  price: 795,
  productPromotions: [{ promotionId: 'final-sale', calloutMsg: 'Final sale — no returns' }],
};

const meta: Meta<typeof StaticProductHeader> = {
  title: 'Commerce/StaticProductHeader',
  component: StaticProductHeader,
  argTypes: {
    name: { control: 'text' },
    currency: { control: 'text' },
    isProductPartOfBundle: { control: 'boolean' },
  },
  decorators: [
    (Story: React.ComponentType) => (
      // MemoryRouter because the base `Breadcrumb` renders react-router `Link`s, which throw
      // outside a Router — preview.tsx supplies Chakra and IntlProvider, but no Router.
      // 218px is the DS info-column width, the same frame zimmProductContent's story uses, so
      // the name's wrap behaviour here matches the real column.
      <MemoryRouter>
        <Box width="218px">
          <Story />
        </Box>
      </MemoryRouter>
    ),
  ],
};
export default meta;

type Story = StoryObj<typeof StaticProductHeader>;

export const Default: Story = {
  name: 'Full product — everything renders',
  args: {
    name: PRODUCT.name,
    product: PRODUCT,
    priceData: { currentPrice: 795 },
    currency: 'AUD',
    category: [
      { id: 'womens', name: 'Womens' },
      { id: 'womens-clothing-dresses', name: 'Dresses' },
    ],
    isProductPartOfBundle: false,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // h2, not h1: the page owns the h1 (a screen-reader-only "Product Details"), so this is
    // the constraint the extraction had to preserve rather than quietly re-level.
    await expect(canvas.getByRole('heading', { level: 2, name: PRODUCT.name })).toBeInTheDocument();

    // Breadcrumb and promo callout are reproduced from the base header rather than dropped,
    // because `renderHeader` replaces the whole block — assert both survived the move.
    await expect(canvas.getByRole('link', { name: 'Dresses' })).toBeInTheDocument();
    await expect(canvas.getByTestId('promo-callout')).toBeInTheDocument();

    // Formatted by the partial's own `useIntl()`, under preview.tsx's en-AU IntlProvider.
    await expect(canvas.getByTestId('product-price')).toHaveTextContent('795');
    await expect(canvas.getByTestId('product-description')).toBeInTheDocument();
  },
};

export const PartOfBundle: Story = {
  name: 'Part of a bundle — price and promo both gated',
  // Default's args with the one flag flipped, so the only thing this story can be proving is the
  // gate. Per the partial's own comment at the price gate, the base header gated its price and
  // its promo together behind `!isProductPartOfBundle`; the extraction kept both, and until this
  // story neither branch was ever entered — every other story here passes `false` or omits it.
  args: {
    name: PRODUCT.name,
    product: PRODUCT,
    priceData: { currentPrice: 795 },
    currency: 'AUD',
    category: [
      { id: 'womens', name: 'Womens' },
      { id: 'womens-clothing-dresses', name: 'Dresses' },
    ],
    isProductPartOfBundle: true,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // The two gated branches, asserted separately: they are independent conditionals on the same
    // flag — the price is gated inside `ZimmProductContent`'s props, the promo by a wrapping
    // `&&` — so either could be dropped without the other noticing.
    await expect(canvas.queryByTestId('product-price')).not.toBeInTheDocument();
    await expect(canvas.queryByTestId('promo-callout')).not.toBeInTheDocument();

    // And the rest of the group is untouched, which is what separates this from `Loading`:
    // `product` and `priceData` are both present here, so an over-broad gate would show up as
    // the name or the description going missing too rather than as a passing test.
    await expect(canvas.getByTestId('product-content')).toBeInTheDocument();
    await expect(canvas.getByRole('heading', { level: 2, name: PRODUCT.name })).toBeInTheDocument();
    await expect(canvas.getByTestId('product-description')).toBeInTheDocument();
  },
};

export const NameOnly: Story = {
  name: 'Product absent, name present — price collapses',
  // ProductView passes `name: product?.name` alongside `product`, so during a variant fetch the
  // name can be known while the product is not. `headerProduct ?? { name }` is the path that
  // keeps the title rendered instead of dropping back to a skeleton.
  args: {
    name: PRODUCT.name,
    product: undefined,
    priceData: undefined,
    currency: 'AUD',
    isProductPartOfBundle: false,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    await expect(canvas.getByRole('heading', { level: 2, name: PRODUCT.name })).toBeInTheDocument();

    // No priceData means the mapper yields '' rather than a formatted NaN, and the price atom
    // renders nothing — so the group collapses to one row instead of reserving an empty one.
    await expect(canvas.queryByTestId('product-price')).not.toBeInTheDocument();
    await expect(canvas.queryByTestId('product-description')).not.toBeInTheDocument();

    // `product` is what gates the promo, so it stays a bare skeleton here.
    await expect(canvas.queryByTestId('promo-callout')).not.toBeInTheDocument();
  },
};

export const Loading: Story = {
  name: 'Neither — the state every page load starts in',
  args: {},
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // `selectPdpProductInfo` returns null without a name, so the content group is absent and
    // only the reserve is on screen.
    await expect(canvas.queryByTestId('product-content')).not.toBeInTheDocument();

    // The reserve itself (D17). An empty SFCC `Skeleton` measures 0px — its baseStyle sets only
    // borderRadius and opacity — so without the explicit minHeight the title would shove the
    // page down when it resolves. 18px is `lineHeights['2xs']` (1.125rem), which is what
    // `--zimm-font-lineheight-2xs` derives from and what ZimmProductName's heading3 renders at.
    // Asserted on the first skeleton by position because an empty one carries no accessible
    // name or test id to select it by, and adding one would change the page's rendered output.
    const reserve = canvasElement.querySelector('.chakra-skeleton');
    await expect(reserve).not.toBeNull();
    await expect(getComputedStyle(reserve as Element).minHeight).toBe('18px');
  },
};

