#!/usr/bin/env node
/**
 * Token usage audit — flags a raw hex colour / px / rem / em literal in an override component
 * or theme recipe, where a Zimmermann token (a foundation constant, a var(--zimm-*) reference,
 * or a Chakra prop resolving through a registered scale) should be used instead.
 *
 * Usage:
 *   node scripts/auditTokenUsage.mjs
 *
 * Scope: overrides/app/components/** and overrides/app/theme/components/** — .ts/.tsx/.scss.
 * Deliberately excludes:
 *   - overrides/app/theme/foundation/ — not under either scan root; these files ARE the source
 *     of truth, so a raw value there is the point, not a violation.
 *   - *.test.ts(x) and *.stories.tsx — test assertions and Storybook demo code routinely need
 *     illustrative/representative raw values that aren't "a hardcoded design value shipped to
 *     production" in the sense this audit cares about (testing.md already treats these
 *     differently from production styling rigor).
 *
 * A match is downgraded from a failure to an ACKNOWLEDGED exception (still printed, does not
 * affect the exit code) when the contiguous non-blank block of lines ending at the match — i.e.
 * the match's own line plus every line above it up to the nearest blank line or file start —
 * contains "provisional", "pending", "placeholder", or an explicit "audit-allow". This is the
 * exact vocabulary this codebase already uses for every documented raw-value exception today
 * (e.g. zimmButton.css.ts's BTN_HEIGHT_LG/BTN_HEIGHT_SM/BTN_PADDING_Y, footer.css.ts's
 * SPACE_SECTION/SIZE_COL_SUB/SIZE_COL_MAP). Reading the existing explanatory comment as the
 * allow-list entry avoids a second, separately-maintained list that would drift from the code
 * the moment either one changes.
 *
 * The "nearest blank line" boundary, not a fixed line count, matters: this codebase's real
 * exception comments are often a shared multi-line block covering several sibling declarations
 * (footer.css.ts's four provisional constants share one comment), or wrap the marker word
 * itself across a line break (zimmSubscribeSection.css.ts had "...52/40. Pending\n// Kiera."
 * — "Pending" and "Kiera" on different lines). A fixed N-line window missed both shapes during
 * this script's own first calibration pass against the real codebase.
 *
 * This is a line-based grep, not an AST parse — matches
 * .claude/rules/overrideStyling.md's own framing ("it greps for exactly this"). A real
 * false-positive class this cannot fully rule out: a hex-looking string in a non-colour
 * context (e.g. a URL fragment that happens to be 3-8 hex characters) would still be flagged;
 * mark it with `// audit-allow: <reason>` rather than trying to make the regex smarter.
 *
 * Not wired into CI yet — see overrideStyling.md's note on why (someone needs to own triaging
 * false positives on a real run first).
 */

import { readFileSync, readdirSync, existsSync } from 'fs';
import { join, extname, relative, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, '..');
const APP = join(ROOT, 'overrides/app');

const SCAN_ROOTS = [join(APP, 'components'), join(APP, 'theme/components')];
const SCAN_EXTENSIONS = new Set(['.ts', '.tsx', '.scss']);

const HEX_RE = /#[0-9a-fA-F]{3,8}\b/g;
const UNIT_RE = /\b\d+(?:\.\d+)?(?:rem|em|px)\b/g;
const EXCEPTION_MARKER_RE = /provisional|pending|placeholder|audit-allow/i;

const isExcludedFile = (filePath) =>
  filePath.endsWith('.test.ts') || filePath.endsWith('.test.tsx') || filePath.endsWith('.stories.tsx');

function walk(dir, files = []) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) {
      walk(full, files);
    } else if (SCAN_EXTENSIONS.has(extname(entry.name)) && !isExcludedFile(full)) {
      files.push(full);
    }
  }
  return files;
}

/**
 * Strips `//` and `/* *\/` comment content from a line so a Figma hex value or px measurement
 * mentioned in prose doesn't get flagged as a code violation. Tracks block-comment state across
 * lines via the mutable `state` object the caller owns. `//` is only treated as a comment start
 * when not immediately preceded by `:` — otherwise `'https://wa.me/...'` string literals (real
 * content in this codebase's Contentful fixtures) would truncate the line early.
 */
function stripComments(line, state) {
  let result = '';
  let i = 0;
  while (i < line.length) {
    if (state.inBlockComment) {
      const end = line.indexOf('*/', i);
      if (end === -1) return result;
      i = end + 2;
      state.inBlockComment = false;
      continue;
    }
    if (line[i] === '/' && line[i + 1] === '/' && line[i - 1] !== ':') break;
    if (line[i] === '/' && line[i + 1] === '*') {
      state.inBlockComment = true;
      i += 2;
      continue;
    }
    result += line[i];
    i += 1;
  }
  return result;
}

function scanFile(filePath) {
  const relPath = relative(ROOT, filePath);
  const lines = readFileSync(filePath, 'utf8').split('\n');
  const state = { inBlockComment: false };
  const findings = [];

  lines.forEach((rawLine, idx) => {
    const lineNo = idx + 1;
    const code = stripComments(rawLine, state);

    const matches = [...code.matchAll(HEX_RE), ...code.matchAll(UNIT_RE)];
    if (matches.length === 0) return;

    let contextStart = idx;
    while (contextStart > 0 && lines[contextStart - 1].trim() !== '') contextStart -= 1;
    const context = lines.slice(contextStart, idx + 1).join('\n');
    const acknowledged = EXCEPTION_MARKER_RE.test(context);

    for (const match of matches) {
      findings.push({ file: relPath, line: lineNo, value: match[0], acknowledged, text: rawLine.trim() });
    }
  });

  return findings;
}

const files = SCAN_ROOTS.filter(existsSync).flatMap((root) => walk(root));
const allFindings = files.flatMap(scanFile);
const failures = allFindings.filter((f) => !f.acknowledged);
const acknowledged = allFindings.filter((f) => f.acknowledged);

console.log('Token usage audit');
console.log('==================');
console.log(`Scanned ${files.length} file(s) under overrides/app/components/ and overrides/app/theme/components/\n`);

if (failures.length > 0) {
  console.log(`❌ ${failures.length} raw value(s) with no acknowledged exception:\n`);
  for (const f of failures) {
    console.log(`  ${f.file}:${f.line}  '${f.value}'`);
    console.log(`    ${f.text}`);
  }
  console.log('\n  Reach for a token instead — var(--zimm-color-*) for hex, var(--zimm-scale-*) for px/rem/em.');
  console.log(
    '  If this genuinely has no token yet (pending UI-designer sign-off), name it as a constant\n' +
      '  with a comment containing "provisional"/"pending"/"placeholder", or add "audit-allow: <reason>".',
  );
}

if (acknowledged.length > 0) {
  console.log(`\n✓ ${acknowledged.length} raw value(s) with an acknowledged exception (not failing):`);
  for (const f of acknowledged) {
    console.log(`  ${f.file}:${f.line}  '${f.value}'`);
  }
}

console.log(
  failures.length > 0
    ? `\n${failures.length} unacknowledged violation(s) found.`
    : '\nNo unacknowledged raw hex/px/rem/em literals found.',
);

process.exit(failures.length > 0 ? 1 : 0);

import type { SystemStyleObject } from '@chakra-ui/react';

// Figma Textfield flush variant (node 40000265:374): field/border/* tokens.
// hover and filled (has value, unfocused) both darken to focus colour per Figma spec.
const BORDER = {
  default: 'var(--zimm-color-border-forms)', // #707070 — Figma field/border/default
  hover: 'var(--zimm-color-border-focus)', // #191919 — Figma field/border/hover
  filled: 'var(--zimm-color-border-focus)', // #191919 — Figma field/border/filled
  focus: 'var(--zimm-color-border-focus)', // #191919 — Figma field/border/focus
  error: 'var(--zimm-color-status-error)', // #9c0000 — Figma field/border/error
} as const;

// Figma field/border/inverse/default = white (opaque), inverse/error = #f98f8c (coral).
// Figma does not spec inverse/hover or inverse/focus separately — same white as default.
const BORDER_INVERSE = {
  default: 'var(--zimm-color-text-inverse)',
  hover: 'var(--zimm-color-text-inverse)',
  filled: 'var(--zimm-color-text-inverse)',
  focus: 'var(--zimm-color-text-inverse)',
  error: 'var(--zimm-color-status-error-bg)', // #f98f8c
} as const;

// Figma: Textfield flush floated label — brand/font/size/250 (10px) / medium weight.
const LABEL_FLOATED_SIZE = 'var(--zimm-font-size-4xs)';
const LABEL_FLOATED_WEIGHT = 'var(--zimm-font-weight-medium)';
// Figma: content div h-[36px] — pending alias/size/field/height token from the designer.
// rem, not px: this height participates in a rem-derived measurement, so it has to scale with the
// root font-size (WCAG 1.4.4 — see overrideStyling.md > Units). footer.css.ts's SIZE_SUBSCRIBE_SLOT
// analogue in zimmSubscribeSection.css.ts (2.8125rem) documents itself as "36px content + 4px/4px
// padding + 1px border"; freezing the content height in px broke that derivation as soon as the
// root font-size moved — at 200% zoom the slot reached 90px while the field reached only 53px,
// over-reserving by ~37px. (Dead space, not clipping — the no-layout-shift guarantee held either
// way.) In rem it holds at every zoom level. This file is now developer-owned per the co-location
// pattern (overrideStyling.md), but the value itself is still PROVISIONAL pending Kiera — this
// should ride along with that sign-off, not land silently.
const FIELD_CONTENT_HEIGHT = '2.25rem'; // 36px at the default 16px root
// No opacity token in foundation yet — pending Tier 1 PR with UI-designer sign-off.
const OPACITY_DISABLED = 0.4;

const MOTION = 'var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard)';

/** State the component feeds in so the recipe can resolve the Figma colour cascade. */
export type ZimmTextInputStyleProps = {
  inverse?: boolean;
  disabled?: boolean;
  hasError?: boolean;
  focused?: boolean;
  /** Field has a value. Combined with `focused` this gives the floated-label state. */
  filled?: boolean;
};

const palette = (inverse?: boolean) => (inverse ? BORDER_INVERSE : BORDER);

/** Border colour precedence: disabled > error > focus > filled > default. */
export const resolveBorderColour = ({ inverse, disabled, hasError, focused, filled }: ZimmTextInputStyleProps) => {
  const p = palette(inverse);
  if (disabled) return p.default;
  if (hasError) return p.error;
  if (focused) return p.focus;
  if (filled) return p.filled;
  return p.default;
};

/** In error the hover colour holds (error > hover); otherwise it darkens to focus. */
export const resolveHoverBorderColour = (props: ZimmTextInputStyleProps) =>
  props.hasError ? resolveBorderColour(props) : palette(props.inverse).hover;

// Figma text/subtle = #666 for the floated/disabled label in light mode;
// text/inverse/subtle = #969696 in inverse mode.
export const resolveLabelColour = ({ inverse, disabled, focused, filled }: ZimmTextInputStyleProps) => {
  const floated = Boolean(focused || filled);
  if (disabled) return inverse ? 'var(--zimm-color-text-inverse-grey)' : 'var(--zimm-color-text-secondary)';
  if (inverse) return floated ? 'var(--zimm-color-text-inverse-grey)' : 'var(--zimm-color-text-inverse)';
  return floated ? 'var(--zimm-color-text-secondary)' : 'var(--zimm-color-text-default)';
};

export const ZimmTextInput = {
  parts: ['root', 'row', 'content', 'label', 'input', 'clearButton', 'helper', 'error'],
  baseStyle: (props: ZimmTextInputStyleProps): Record<string, SystemStyleObject> => {
    const { inverse, disabled, focused, filled } = props;
    const floated = Boolean(focused || filled);
    const textColour = inverse ? 'var(--zimm-color-text-inverse)' : 'var(--zimm-color-text-default)';

    return {
      root: {
        display: 'block',
        width: '100%',
        opacity: disabled ? OPACITY_DISABLED : 1,
      },

      // Flush bottom-border row. Hover is a CSS pseudo-class, not JS state.
      row: {
        display: 'flex',
        alignItems: 'center',
        gap: 'var(--zimm-scale-xs)',
        borderBottom: `var(--zimm-border-width-default) solid ${resolveBorderColour(props)}`,
        paddingTop: 'var(--zimm-scale-2xs)',
        paddingBottom: 'var(--zimm-scale-2xs)',
        // not in Figma — UX animation on border-colour state changes
        transition: `border-color ${MOTION}`,
        _hover: disabled ? undefined : { borderBottomColor: resolveHoverBorderColour(props) },
      },

      // Figma: content flex-[1_0_0] h-[36px]
      content: { flex: 1, position: 'relative', minHeight: FIELD_CONTENT_HEIGHT },

      label: {
        position: 'absolute',
        left: 0,
        fontFamily: 'var(--zimm-font-family-body)',
        fontWeight: floated ? LABEL_FLOATED_WEIGHT : 'var(--zimm-font-weight-regular)',
        fontSize: floated ? LABEL_FLOATED_SIZE : 'var(--zimm-font-size-2xs)',
        lineHeight: floated ? undefined : 'var(--zimm-font-lineheight-2xs)',
        color: resolveLabelColour(props),
        top: floated ? 'var(--zimm-scale-3xs)' : '50%',
        transform: floated ? 'none' : 'translateY(-50%)',
        transition: `top ${MOTION}, transform ${MOTION}, font-size ${MOTION}, color ${MOTION}`,
        whiteSpace: 'nowrap',
      },

      input: {
        position: 'absolute',
        bottom: 0,
        left: 0,
        right: 0,
        width: '100%',
        height: 'var(--zimm-scale-l)', // 20px — var, not 'l': theme.sizes has no 'l' key
        background: 'transparent',
        border: 'none',
        outline: 'none',
        fontFamily: 'var(--zimm-font-family-body)',
        fontWeight: 'var(--zimm-font-weight-regular)',
        fontSize: 'var(--zimm-font-size-2xs)',
        color: textColour,
        padding: 0,
        opacity: floated ? 1 : 0,
        cursor: disabled ? 'not-allowed' : 'text',
        transition: `opacity ${MOTION}`,
      },

      clearButton: {
        background: 'transparent',
        border: 'none',
        padding: 0,
        cursor: 'pointer',
        display: 'inline-flex',
        alignItems: 'center',
        justifyContent: 'center',
        flexShrink: 0,
        color: textColour,
        // WCAG 2.2 AA SC 2.5.8 — 24px minimum target size
        // var, not 'xl': min-width/height resolve via theme.sizes (xl = 36rem), not theme.space
        minWidth: 'var(--zimm-scale-xl)',
        minHeight: 'var(--zimm-scale-xl)',
        // WCAG 2.2 AA SC 2.4.7 — visible focus state
        _focusVisible: {
          outline: inverse
            ? 'var(--zimm-border-width-default) solid var(--zimm-color-text-inverse)'
            : 'var(--zimm-focus-ring)',
          outlineOffset: 'var(--zimm-focus-ring-offset-default)',
          boxShadow: 'none',
        },
      },

      helper: {
        marginTop: 'var(--zimm-scale-2xs)',
        marginBottom: 0,
        marginInline: 0,
        fontFamily: 'var(--zimm-font-family-body)',
        fontSize: 'var(--zimm-font-size-3xs)',
        color: inverse ? 'var(--zimm-color-text-inverse-grey)' : 'var(--zimm-color-text-secondary)',
      },

      error: {
        marginTop: 'var(--zimm-scale-2xs)',
        marginBottom: 0,
        marginInline: 0,
        fontFamily: 'var(--zimm-font-family-body)',
        fontSize: 'var(--zimm-font-size-2xs)',
        fontStyle: 'normal',
        fontWeight: 'var(--zimm-font-weight-regular)',
        lineHeight: 'var(--zimm-font-lineheight-2xs)',
        color: inverse ? 'var(--zimm-color-status-error-bg)' : 'var(--zimm-color-status-error)',
      },
    };
  },
};

